import numpy as np,json,sys
from PIL import Image
from rcb_client import Robot
r=Robot();s=r.spec();ran=np.array(s['qpos']['range']);lo=ran[:,0];hi=ran[:,1]

def action(q):return np.clip(2*(np.array(q)-lo)/(hi-lo)-1,-1,1)
def save(o):
 np.savez('/app/output/obs.npz',q=o['proprio']['joint_pos'],v=o['proprio']['joint_vel'],g=o['imu']['gravity'],w=o['imu']['gyro'])
 for k,v in o.get('images',{}).items():Image.fromarray(v).save('/app/output/'+k+'.png')
 print(json.dumps({k:v for k,v in o.items() if k not in ['images','depth']}))
def step(q,n=1):
 a=action(q);o=r.step('qpos',np.tile(a,(n,1)).tolist(),images=True)
 with open('/app/output/actions.jsonl','a') as f:
  for _ in range(o.get('executed',n)):f.write(json.dumps(a.tolist())+'\n')
 save(o);return o
if __name__=='__main__':
 if sys.argv[1]=='obs':save(r.observe())
 elif sys.argv[1]=='reset':
  o=r.reset();open('/app/output/actions.jsonl','w').close();save(o)
 elif sys.argv[1]=='step':
  q=np.load('/app/output/obs.npz')['q'];d=json.loads(sys.argv[2]);n=int(sys.argv[3]);
  if isinstance(d,list):q=np.array(d)
  else:
   for k,v in d.items():q[s['qpos']['layout'].index(k) if k in s['qpos']['layout'] else int(k)]=v
  step(q,n)
